36: // Per-thread data, aligned to cachelines to avoid false sharing
37: struct LIBASYNC_CACHELINE_ALIGN thread_data_t {
38: 	work_steal_queue queue;
39: 	std::minstd_rand rng;
40: 	std::thread handle;
