148: // Try to steal a task from another thread's queue
149: static task_run_handle steal_task(threadpool_data* impl, std::size_t thread_id)
150: {
151: 	// Make a list of victim thread ids and shuffle it
152: 	std::vector<std::size_t> victims(impl->thread_data.size());
153: 	std::iota(victims.begin(), victims.end(), 0);
154: 	std::shuffle(victims.begin(), victims.end(), impl->thread_data[thread_id].rng);
155: 
156: 	// Try to steal from another thread
157: 	for (std::size_t i: victims) {
158: 		// Don't try to steal from ourself
159: 		if (i == thread_id)
160: 			continue;
161: 
162: 		if (task_run_handle t = impl->thread_data[i].queue.steal())
163: 			return t;
164: 	}
165: 
166: 	// No tasks found, but we might have missed one if it was just added. In
167: 	// practice this doesn't really matter since it will be handled by another
168: 	// thread.
169: 	return task_run_handle();
170: }
171: 
172: // Main task stealing loop which is used by worker threads when they have
173: // nothing to do.
174: static void thread_task_loop(threadpool_data* impl, std::size_t thread_id, task_wait_handle wait_task)
175: {
176: 	// Get our thread's data
177: 	thread_data_t& current_thread = impl->thread_data[thread_id];
178: 
179: 	// Flag indicating if we have added a continuation to the task
180: 	bool added_continuation = false;
181: 
182: 	// Event to wait on
183: 	task_wait_event event;
184: 
185: 	// Loop while waiting for the task to complete
186: 	while (true) {
187: 		// Check if the task has finished. If we have added a continuation, we
188: 		// need to make sure the event has been signaled, otherwise the other
189: 		// thread may try to signal it after we have freed it.
190: 		if (wait_task && (added_continuation ? event.try_wait(wait_type::task_finished) : wait_task.ready()))
191: 			return;
192: 
193: 		// Try to get a task from the local queue
194: 		if (task_run_handle t = current_thread.queue.pop()) {
195: 			t.run();
196: 			continue;
197: 		}
198: 
199: 		// Stealing loop
200: 		while (true) {
201: 			// Try to steal a task
202: 			if (task_run_handle t = steal_task(impl, thread_id)) {
203: 				t.run();
204: 				break;
205: 			}
206: 
207: 			// Try to fetch from the public queue
208: 			std::unique_lock<std::mutex> locked(impl->lock);
209: 			if (task_run_handle t = impl->public_queue.pop()) {
210: 				// Don't hold the lock while running the task
211: 				locked.unlock();
212: 				t.run();
213: 				break;
214: 			}
215: 
216: 			// If shutting down and we don't have a task to wait for, return.
217: 			if (!wait_task && impl->shutdown) {
218: #ifdef BROKEN_JOIN_IN_DESTRUCTOR
219: 				// Notify once all worker threads have exited
220: 				if (--impl->shutdown_num_threads == 0)
221: 					impl->shutdown_complete_event.notify_one();
222: #endif
223: 				return;
224: 			}
225: 
226: 			// Initialize the event object
227: 			event.init();
228: 
229: 			// No tasks found, so sleep until something happens.
230: 			// If a continuation has not been added yet, add it.
231: 			if (wait_task && !added_continuation) {
232: 				// Create a continuation for the task we are waiting for
233: 				wait_task.on_finish([&event] {
234: 					// Signal the thread's event
235: 					event.signal(wait_type::task_finished);
236: 				});
237: 				added_continuation = true;
238: 			}
239: 
240: 			// Add our thread to the list of waiting threads
241: 			size_t num_waiters_val = impl->num_waiters.load(std::memory_order_relaxed);
242: 			impl->waiters[num_waiters_val] = &event;
243: 			impl->num_waiters.store(num_waiters_val + 1, std::memory_order_relaxed);
244: 
245: 			// Wait for our event to be signaled when a task is scheduled or
246: 			// the task we are waiting for has completed.
247: 			locked.unlock();
248: 			int events = event.wait();
249: 			locked.lock();
250: 
251: 			// Remove our thread from the list of waiting threads
252: 			num_waiters_val = impl->num_waiters.load(std::memory_order_relaxed);
253: 			for (std::size_t i = 0; i < num_waiters_val; i++) {
254: 				if (impl->waiters[i] == &event) {
255: 					if (i != num_waiters_val - 1)
256: 						std::swap(impl->waiters[i], impl->waiters[num_waiters_val - 1]);
257: 					impl->num_waiters.store(num_waiters_val - 1, std::memory_order_relaxed);
258: 					break;
259: 				}
260: 			}
261: 
262: 			// Check again if the task has finished. We have added a
263: 			// continuation at this point, so we need to check that the
264: 			// continuation has finished signaling the event.
265: 			if (wait_task && (events & wait_type::task_finished))
266: 				return;
267: 		}
268: 	}
269: }
